68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /**
76	     * Dedicated logger for the welcome notification enqueued when an owner is successfully created.
77	     * The emitted line carries the owner's id and its unified {@link Owner#getMemberId() memberId} so
78	     * downstream notification consumers can address the welcome to the newly registered owner.
79	     */
80	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
81	
82	    /**
83	     * Serializes {@link OwnerCreatedEvent structured audit events} to their JSON form. Stateless and
84	     * thread-safe, so a single shared instance serves every create.
85	     */
86	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
87	
88	    /**
89	     * Monotonically increasing sequence stamped onto each {@link OwnerCreatedEvent OWNER_CREATED}
90	     * event, so the ordering of creates is recoverable from the audit stream alone. Shared across all
91	     * creates (hence {@code static}) and incremented once per emitted event.
92	     */
93	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
94	
95	    /**
96	     * Immutable structured audit event emitted (as JSON) alongside the human-readable audit line when
97	     * an owner is created. Its {@code memberId} component carries the owner's <em>primary
98	     * identifier</em>, the unified {@link Owner#getMemberId() memberId}, so downstream consumers always
99	     * read the owner's primary identifier from the same event.
100	     *
101	     * <p>The component order matches the serialized field order
102	     * {@code {seq, ownerId, memberId, membershipLevel, event}}.
103	     */
104	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
105	                                     Integer membershipLevel, String event) {
106	
107	        private static final String OWNER_CREATED = "OWNER_CREATED";
108	
109	        static OwnerCreatedEvent of(long seq, Owner owner) {
110	            return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
111	                owner.getMembershipLevel(), OWNER_CREATED);
112	        }
113	
114	        /**
115	         * The owner's primary identifier: its unified {@link Owner#getMemberId() memberId}.
116	         */
117	        private static String primaryIdentifier(Owner owner) {
118	            return owner.getMemberId();
119	        }
120	    }
121	
122	    /**
123	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
124	     * with a key already seen, the originally created owner is returned instead of a duplicate.
125	     */
126	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
127	
128	    /**
129	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
130	     * first successful create produced, so a repeat of that create can return the same owner rather
131	     * than creating a duplicate.
132	     */
133	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
134	
135	    /**
136	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
137	     * forward to the next non-holiday business day, in the same way weekends are.
138	     */
139	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
140	        LocalDate.of(2026, 1, 1),
141	        LocalDate.of(2026, 1, 26),
142	        LocalDate.of(2026, 4, 25),
143	        LocalDate.of(2026, 12, 25),
144	        LocalDate.of(2026, 12, 28));
145	
146	    private final ClinicService clinicService;
147	
148	    private final OwnerMapper ownerMapper;
149	
150	    private final PetMapper petMapper;
151	
152	    private final VisitMapper visitMapper;
153	
154	    private final AddressNormalizer addressNormalizer;
155	
156	    public OwnerRestControllerV1(ClinicService clinicService,
157	                                 OwnerMapper ownerMapper,
158	                                 PetMapper petMapper,
159	                                 VisitMapper visitMapper,
160	                                 AddressNormalizer addressNormalizer) {
161	        this.clinicService = clinicService;
162	        this.ownerMapper = ownerMapper;
163	        this.petMapper = petMapper;
164	        this.visitMapper = visitMapper;
165	        this.addressNormalizer = addressNormalizer;
166	    }
