216	    /**
217	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
218	     * being handled, or {@code null} when the request carries no such header (or no request is bound
219	     * to the current thread). Used to make a repeated create return the originally created owner.
220	     */
221	    private String currentIdempotencyKey() {
222	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
223	            return null;
224	        }
225	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
226	        return (key == null || key.isBlank()) ? null : key;
227	    }
228	
229	    /**
230	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
231	     * response. The submitted fields are mapped to an {@link Owner}, which is
232	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
233	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
234	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
235	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
236	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
237	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
238	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
239	     * cannot be created.
240	     */
241	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
242	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
243	
244	        HttpStatus invalid = normalizeAndValidate(owner);
245	        if (invalid != null) {
246	            return new ResponseEntity<>(invalid);
247	        }
248	        if (isDailyLimitReached(owner.getRegistrationDate())) {
249	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
250	        }
251	
252	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
253	        assignHousehold(owner);
254	
255	        HttpStatus conflict = checkForConflicts(owner);
256	        if (conflict != null) {
257	            return new ResponseEntity<>(conflict);
258	        }
259	
260	        assignDerivedAttributes(owner, sharesHousehold);
261	        this.clinicService.saveOwner(owner);
262	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
263	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
264	            owner.getMembershipLevel());
265	        emitOwnerCreatedEvent(owner);
266	        enqueueWelcomeNotification(owner);
267	        return created(owner);
268	    }
269	
270	    /**
271	     * Enqueue a welcome notification for a just-created owner by emitting a line on the {@code NOTIFY}
272	     * logger that carries the owner's id and its unified {@link Owner#getMemberId() memberId}, so a
273	     * downstream consumer can address the welcome to the newly registered owner.
274	     */
275	    private void enqueueWelcomeNotification(Owner owner) {
276	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
277	    }
278	
279	    /**
280	     * Emit the immutable {@link OwnerCreatedEvent} for a just-persisted owner as a JSON object on the
281	     * {@code AUDIT} logger. A fresh {@link #AUDIT_SEQ monotonic sequence} is stamped onto the event so
282	     * the order of creates is recoverable from the audit stream. The event carries the owner's primary
283	     * identifier, its unified memberId.
284	     */
285	    private void emitOwnerCreatedEvent(Owner owner) {
286	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_SEQ.incrementAndGet(), owner);
287	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
288	    }
289	
290	    /**
291	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
292	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
293	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
294	     * postcode is checked against its city's region, a registration date in the future is rejected,
295	     * and the effective registration date (the supplied one, or today when none was given) is rolled
296	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
297	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
298	     * otherwise.
299	     */
300	    private HttpStatus normalizeAndValidate(Owner owner) {
301	        if (!normalizeAddress(owner)) {
302	            return HttpStatus.BAD_REQUEST;
303	        }
304	        String telephone = toE164(owner.getTelephone());
305	        if (telephone == null) {
306	            return HttpStatus.BAD_REQUEST;
307	        }
308	        owner.setTelephone(telephone);
309	        if (isDisposableEmail(owner.getEmail())) {
310	            return HttpStatus.BAD_REQUEST;
311	        }
312	        if (!owner.isPostcodeValid()) {
313	            return HttpStatus.BAD_REQUEST;
314	        }
315	        if (owner.getRegistrationDate() != null
316	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
317	            return HttpStatus.BAD_REQUEST;
318	        }
319	        LocalDate effectiveDate = owner.getRegistrationDate() != null
320	            ? owner.getRegistrationDate() : LocalDate.now();
321	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
322	        return null;
323	    }
324	
325	    /**
326	     * Normalize the owner's supplied address into its canonical stored form and report whether an
327	     * address was supplied at all. The owner may supply its address either as the structured
328	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
329	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
330	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
331	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
332	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
333	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
334	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
335	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
336	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
337	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
338	     * create must be rejected with {@code 400 Bad Request}.
339	     */
340	    private boolean normalizeAddress(Owner owner) {
341	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
342	        if (!line1.isEmpty()) {
343	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
344	            owner.setAddressLine1(line1);
345	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
346	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
347	            return true;
348	        }
349	        String address = addressNormalizer.normalize(owner.getAddress());
350	        if (address.isEmpty()) {
351	            return false;
352	        }
353	        owner.setAddressLine1(null);
354	        owner.setAddressLine2(null);
355	        owner.setAddress(address);
356	        return true;
357	    }
358	
359	    /**
360	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
361	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
362	     */
363	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
364	        "mailinator.com", "tempmail.com", "guerrillamail.com");
365	
366	    /**
367	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
368	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
369	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is matched
370	     * against the blocklist.
371	     */
372	    private boolean isDisposableEmail(String email) {
373	        String domain = Owner.emailDomainOf(email);
374	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
375	    }
