390	    /**
391	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
392	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
393	     * {@linkplain #isDuplicateIdentity(Owner) duplicates an existing owner's identity key} or when
394	     * its {@link #isCityAtCapacity(String) city is already at capacity}. Sharing a household (the
395	     * same surname sound and postcode) but with a different identity key is not a conflict: such an
396	     * owner is admitted and later {@linkplain #findSoftDuplicate(Owner) flagged as a possible
397	     * duplicate}. Returns {@code null} when the owner clashes with nothing and may be created.
398	     */
399	    private HttpStatus checkForConflicts(Owner owner) {
400	        if (isDuplicateIdentity(owner)) {
401	            return HttpStatus.CONFLICT;
402	        }
403	        if (isCityAtCapacity(owner.getCity())) {
404	            return HttpStatus.CONFLICT;
405	        }
406	        return null;
407	    }
408	
409	    /**
410	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
411	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
412	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
413	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
414	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
415	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
416	     * disposable-email owner is rejected before it reaches this check.
417	     */
418	    private boolean isDuplicateIdentity(Owner owner) {
419	        String identityKey = owner.getIdentityKey();
420	        return activeOwners().stream()
421	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
422	    }
423	
424	    /**
425	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
426	     * {@code Location} header pointing at {@code /api/owners/{id}}.
427	     */
428	    private ResponseEntity<OwnerDto> created(Owner owner) {
429	        HttpHeaders headers = new HttpHeaders();
430	        headers.setLocation(UriComponentsBuilder.newInstance()
431	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
432	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
433	    }
434	
435	    /**
436	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
437	     * {@link #memberId(Owner) memberId}, {@link #namesakeCount(String, String) namesakeCount},
438	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #isCityApproachingCapacity(String)
439	     * capacity warning}, {@link #householdSize(String)
440	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
441	     * owner's own fields together with the owners already present, so this runs after the owner has
442	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
443	     * persisted.
444	     */
445	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
446	        owner.setMemberId(memberId(owner));
447	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
448	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
449	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
450	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
451	        owner.setMembershipLevel(membershipLevel(owner));
452	        assignPossibleDuplicate(owner, sharesHousehold);
453	    }
454	
455	    /**
456	     * The membership level to assign a newly created owner and store on it as its
457	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
458	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
459	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
460	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
461	     * member no cap applies and the base level is used as-is. This is the single place the stored
462	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
463	     * after the owner has passed the duplicate and capacity checks and so has its household members
464	     * available to it.
465	     */
466	    private Integer membershipLevel(Owner owner) {
467	        int base = owner.getBaseMembershipLevel();
468	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
469	        if (members.isEmpty()) {
470	            return base;
471	        }
472	        int householdMax = members.stream()
473	            .mapToInt(Owner::getMembershipLevel)
474	            .max()
475	            .getAsInt();
476	        return Math.min(base, householdMax + 1);
477	    }
478	
479	    /**
480	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
481	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
482	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
483	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
484	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
485	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
486	     */
487	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
488	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
489	        owner.setPossibleDuplicate(match != null);
490	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
491	    }
492	
493	    /**
494	     * The owners a newly created owner is checked against by the duplicate and identity rules:
495	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
496	     * soft-duplicate} checks, the {@link #memberId(Owner) memberId} de-duplication and the
497	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
498	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
499	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
500	     * soft delete retains but excludes from duplicate and identity detection.
501	     */
502	    private Collection<Owner> activeOwners() {
503	        return this.clinicService.findAllOwners().stream()
504	            .filter(owner -> !owner.isDeleted())
505	            .collect(Collectors.toList());
506	    }
507	
508	    /**
509	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
510	     * match is an existing owner whose {@link Owner#getIdentityKey() identity key} differs from this
511	     * owner's (so it is not already a hard duplicate) but whose lastName has the same
512	     * {@link Owner#soundex(String) soundex} and whose postcode matches; the earliest such owner (by
513	     * id) is returned. Two owners sharing a surname sound and postcode but differing in telephone (or
514	     * email) therefore surface here as a soft match rather than being rejected. A postcode is required
515	     * for a soft match, so an owner without a postcode never matches.
516	     */
517	    private Owner findSoftDuplicate(Owner owner) {
518	        if (owner.getPostcode() == null) {
519	            return null;
520	        }
521	        String candidateSoundex = Owner.soundex(owner.getLastName());
522	        String identityKey = owner.getIdentityKey();
523	        return activeOwners().stream()
524	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
525	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(candidateSoundex))
526	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
527	            .min(Comparator.comparingInt(Owner::getId))
528	            .orElse(null);
529	    }
530	
531	    /**
532	     * Build the memberId for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
533	     * region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION} when the postcode is
534	     * absent or maps to no known region), the 2-digit fiscal-year code FY of the business-day-adjusted
535	     * registrationDate, the first 8 upper-case hex characters HASH8 of the SHA-256 of the normalized
536	     * (E.164) telephone concatenated with the lastName, and a single Luhn check digit CHK over the
537	     * decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW273C1A9F2B4'}). The
538	     * {@code <REGION><FY><HASH8><CHK>} value is computed by {@link Owner#computeMemberId()}; this is
539	     * the single source of the owner's identity, from which the owner's locality and fiscal year are
540	     * read back.
541	     *
542	     * <p>When the computed memberId collides with an existing owner's {@code memberId}, a
543	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the
544	     * memberId unique, and the de-duplicated memberId is returned.
545	     */
546	    private String memberId(Owner owner) {
547	        String base = owner.computeMemberId();
548	
549	        Set<String> existingIds = activeOwners().stream()
550	            .map(Owner::getMemberId)
551	            .filter(Objects::nonNull)
552	            .collect(Collectors.toSet());
553	
554	        if (!existingIds.contains(base)) {
555	            return base;
556	        }
557	        int n = 2;
558	        while (existingIds.contains(base + "-" + n)) {
559	            n++;
560	        }
561	        return base + "-" + n;
562	    }
563	
564	    /**
565	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
566	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
567	     * (business-day) registration date of the owner being created, so owners are counted per
568	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
569	     */
570	    private boolean isDailyLimitReached(LocalDate day) {
571	        long count = this.clinicService.findAllOwners().stream()
572	            .filter(existing -> day.equals(existing.getRegistrationDate()))
573	            .count();
574	        return count >= 100;
575	    }
576	
577	    /**
578	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
579	     * more than 80 owners have already been created for the given business day. Counts the owners
580	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
581	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
582	     * warning.
583	     */
584	    private boolean isBulkSignup(LocalDate day) {
585	        long count = this.clinicService.findAllOwners().stream()
586	            .filter(existing -> day.equals(existing.getRegistrationDate()))
587	            .count();
588	        return count > 80;
589	    }
590	
591	    /**
592	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
593	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
594	     * returned unchanged.
595	     */
596	    private LocalDate toBusinessDay(LocalDate date) {
597	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
598	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
599	            || PUBLIC_HOLIDAYS.contains(date)) {
600	            date = date.plusDays(1);
601	        }
602	        return date;
603	    }
604	
605	    /**
606	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
607	     * more owners. Cities are compared case-insensitively.
608	     */
609	    private boolean isCityAtCapacity(String city) {
610	        return cityOwnerCount(city) >= 50;
611	    }
612	
613	    /**
614	     * Whether the given city is approaching its owner capacity, i.e. it already contains between 40
615	     * and 49 owners (inclusive) and so is nearing the {@link #isCityAtCapacity(String) hard capacity
616	     * limit} of 50. When true, a newly created owner in that city is flagged with a
617	     * {@code capacityWarning}; the hard rejection at 50 is unchanged. Cities are compared
618	     * case-insensitively.
619	     */
620	    private boolean isCityApproachingCapacity(String city) {
621	        long count = cityOwnerCount(city);
622	        return count >= 40 && count <= 49;
623	    }
624	
625	    /**
626	     * The number of existing owners in the given city, compared case-insensitively. Counted over the
627	     * owners present before this create.
628	     */
629	    private long cityOwnerCount(String city) {
630	        return this.clinicService.findAllOwners().stream()
631	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
632	            .count();
633	    }
634	
635	    /**
636	     * The number of existing owners that already share the given firstName and lastName,
637	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
638	     * whitespace runs collapsed). Counted over the owners present before this create.
639	     */
640	    private int namesakeCount(String firstName, String lastName) {
641	        String candidateFirstName = normalizeName(firstName);
642	        String candidateLastName = normalizeName(lastName);
643	        return (int) activeOwners().stream()
644	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
645	                && normalizeName(existing.getLastName()).equals(candidateLastName))
646	            .count();
647	    }
648	
649	    /**
650	     * The number of members in this owner's household after this create: the count of existing
651	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
652	     * created. An owner with no household ({@code householdId == null}) is a household of one.
653	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
654	     * does not depend on the order in which household members were created.
655	     */
656	    private int householdSize(String householdId) {
657	        if (householdId == null) {
658	            return 1;
659	        }
660	        long existing = this.clinicService.findAllOwners().stream()
661	            .filter(other -> householdId.equals(other.getHouseholdId()))
662	            .count();
663	        return (int) existing + 1;
664	    }
665	
666	    /**
667	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
668	     * cannot form a valid E.164 number.
669	     *
670	     * <p>A leading '+' and country code are kept when present; otherwise country code
671	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
672	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
673	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
674	     * exactly the national-digit count that code requires (see
675	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
676	     */
677	    private String toE164(String telephone) {
678	        if (telephone == null) {
679	            return null;
680	        }
681	        boolean hasCountryCode = telephone.trim().startsWith("+");
682	        String digits = telephone.replaceAll("\\D", "");
683	        String e164;
684	        if (hasCountryCode) {
685	            e164 = digits;
686	        } else {
687	            if (digits.startsWith("0")) {
688	                digits = digits.substring(1);
689	            }
690	            e164 = "61" + digits;
691	        }
692	        if (e164.length() < 8 || e164.length() > 15) {
693	            return null;
694	        }
695	        if (!Owner.hasValidNationalLength(e164)) {
696	            return null;
697	        }
698	        return "+" + e164;
699	    }
700	
701	    /**
702	     * The existing owners already registered in the household identified by {@code householdId}: the
703	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
704	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
705	     * (an owner with no household) yields an empty collection. This is the single source of a
706	     * household's existing membership, shared by every rule keyed by an owner's household (the
707	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
708	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
709	     * owners.
710	     */
711	    private Collection<Owner> householdMembers(String householdId) {
712	        if (householdId == null) {
713	            return List.of();
714	        }
715	        return activeOwners().stream()
716	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
717	            .collect(Collectors.toList());
718	    }
719	
720	    /**
721	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
722	     * to a single space and lower-case. A null value normalizes to the empty string.
723	     */
724	    private String normalizeName(String value) {
725	        if (value == null) {
726	            return "";
727	        }
728	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
729	    }
730	
731	    /**
732	     * A stable shared identifier for the household an owner belongs to, derived deterministically
733	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
734	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
735	     * assigned the same value regardless of the order in which they are created. Formatted as the
736	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
737	     * (an absent postcode contributes the empty string).
738	     */
739	    private String householdId(Owner owner) {
740	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
741	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
742	        return shaHexUpper(key).substring(0, 12);
743	    }
744	
745	    /**
746	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
747	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
748	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
749	     * first 12 characters). The hashing itself lives in {@link HashUtils} so the one implementation is
750	     * shared with the owner's {@link Owner#getIdentityKey() identity key} and its
751	     * {@link Owner#computeMemberId() memberId} HASH8.
752	     */
753	    private String shaHexUpper(String input) {
754	        return HashUtils.sha256Hex(input).toUpperCase();
755	    }
756	
757	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
758	    @Override
759	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
760	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
761	        if (currentOwner == null) {
762	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
763	        }
764	        currentOwner.setAddress(ownerFieldsDto.getAddress());
765	        currentOwner.setCity(ownerFieldsDto.getCity());
766	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
767	        currentOwner.setLastName(ownerFieldsDto.getLastName());
768	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
769	        this.clinicService.saveOwner(currentOwner);
770	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
771	    }
772	
773	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
774	    @Transactional
775	    @Override
776	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
777	        Owner owner = this.clinicService.findOwnerById(ownerId);
778	        if (owner == null) {
779	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
780	        }
781	        this.clinicService.deleteOwner(owner);
782	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
783	    }
784	
785	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
786	    @Override
787	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
788	        Owner owner = this.clinicService.findOwnerById(ownerId);
789	        if (owner == null) {
790	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
791	        }
792	        HttpHeaders headers = new HttpHeaders();
793	        Pet pet = petMapper.toPet(petFieldsDto);
794	        owner.setId(ownerId);
795	        pet.setOwner(owner);
796	        pet.getType().setName(null);
797	        this.clinicService.savePet(pet);
798	        PetDto petDto = petMapper.toPetDto(pet);
799	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
800	            .buildAndExpand(pet.getId()).toUri());
801	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
802	    }
803	
804	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
805	    @Override
806	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
807	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
808	        if (currentOwner != null) {
809	            Pet currentPet = this.clinicService.findPetById(petId);
810	            if (currentPet != null) {
811	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
812	                currentPet.setName(petFieldsDto.getName());
813	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
814	                this.clinicService.savePet(currentPet);
815	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
816	            }
817	        }
818	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
819	    }
820	
821	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
822	    @Override
823	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
824	        HttpHeaders headers = new HttpHeaders();
825	        Visit visit = visitMapper.toVisit(visitFieldsDto);
826	        Pet pet = new Pet();
827	        pet.setId(petId);
828	        visit.setPet(pet);
829	        this.clinicService.saveVisit(visit);
830	        VisitDto visitDto = visitMapper.toVisitDto(visit);
831	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
832	            .buildAndExpand(visit.getId()).toUri());
833	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
834	    }
835	
836	
837	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
838	    @Override
839	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
840	        Owner owner = this.clinicService.findOwnerById(ownerId);
841	        if (owner != null) {
842	            Pet pet = owner.getPet(petId);
843	            if (pet != null) {
844	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
845	            }
846	        }
847	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
848	    }
849	}
